import React, { Component } from 'react';
import PropTypes from 'prop-types';
import { bindActionCreators } from 'redux';
import { connect } from 'react-redux';

import Translator from './translator/translator';
import Catalog from './catalog/catalog';
import actions from './actions/export';
import { objectsMap } from './utils/objects-utils';
import {
  ToolbarComponents,
  Content,
  SidebarComponents,
  FooterBarComponents
} from './components/export';
import MobileToolbar from './components/toolbar/mobile-toolbar';
import SidebarDrawer from './components/sidebar/sidebar-drawer';
import { VERSION } from './version';
import './styles/export';

const { Toolbar } = ToolbarComponents;
const { Sidebar } = SidebarComponents;
const { FooterBar } = FooterBarComponents;

// Desktop dimensions
const DESKTOP_TOOLBAR_W = 50;
const DESKTOP_SIDEBAR_W = 300;
const DESKTOP_FOOTER_H = 20;

// Mobile dimensions
const MOBILE_TOOLBAR_H = 60;
const MOBILE_BREAKPOINT = 768;

const wrapperStyle = {
  display: 'flex',
  flexFlow: 'row nowrap'
};

const mobileWrapperStyle = {
  display: 'flex',
  flexFlow: 'column nowrap',
  position: 'relative'
};

class ReactPlanner extends Component {

  constructor(props, context) {
    super(props, context);
    this.state = {
      isMobile: typeof window !== 'undefined' ? window.innerWidth < MOBILE_BREAKPOINT : false,
      drawerOpen: false
    };
    this.handleResize = this.handleResize.bind(this);
    this.toggleDrawer = this.toggleDrawer.bind(this);
    this.closeDrawer = this.closeDrawer.bind(this);
  }

  getChildContext() {
    return {
      ...objectsMap(actions, actionNamespace => this.props[actionNamespace]),
      translator: this.props.translator,
      catalog: this.props.catalog,
    }
  }

  componentWillMount() {
    let { store } = this.context;
    let { projectActions, catalog, stateExtractor, plugins } = this.props;
    plugins.forEach(plugin => plugin(store, stateExtractor));
    projectActions.initCatalog(catalog);
  }

  componentDidMount() {
    if (typeof window !== 'undefined') {
      window.addEventListener('resize', this.handleResize);
    }
  }

  componentWillUnmount() {
    if (typeof window !== 'undefined') {
      window.removeEventListener('resize', this.handleResize);
    }
  }

  handleResize() {
    const isMobile = window.innerWidth < MOBILE_BREAKPOINT;
    if (isMobile !== this.state.isMobile) {
      this.setState({ isMobile, drawerOpen: false });
    }
  }

  toggleDrawer() {
    this.setState(prevState => ({ drawerOpen: !prevState.drawerOpen }));
  }

  closeDrawer() {
    this.setState({ drawerOpen: false });
  }

  componentWillReceiveProps(nextProps) {
    let { stateExtractor, state, projectActions, catalog } = nextProps;
    let plannerState = stateExtractor(state);
    let catalogReady = plannerState.getIn(['catalog', 'ready']);
    if (!catalogReady) {
      projectActions.initCatalog(catalog);
    }
  }

  render() {
    let { width, height, state, stateExtractor, ...props } = this.props;
    let { isMobile, drawerOpen } = this.state;

    let extractedState = stateExtractor(state);

    // Mobile Layout
    if (isMobile) {
      // Use full height, toolbar is fixed at bottom
      // Add padding to account for toolbar + safe area
      const safeAreaPadding = 80; // toolbar height + extra for safe area
      let contentH = height - safeAreaPadding;

      return (
        <div style={{ ...mobileWrapperStyle, height, paddingBottom: safeAreaPadding }}>
          <Content
            width={width}
            height={contentH}
            state={extractedState}
            {...props}
            onWheel={event => event.preventDefault()}
          />
          <MobileToolbar
            width={width}
            height={MOBILE_TOOLBAR_H}
            state={extractedState}
            onMenuClick={this.toggleDrawer}
            {...props}
          />
          <SidebarDrawer
            isOpen={drawerOpen}
            onClose={this.closeDrawer}
            width={Math.min(300, width * 0.85)}
            height={height}
            state={extractedState}
            {...props}
          />
        </div>
      );
    }

    // Desktop Layout (unchanged)
    let contentW = width - DESKTOP_TOOLBAR_W - DESKTOP_SIDEBAR_W;
    let toolbarH = height - DESKTOP_FOOTER_H;
    let contentH = height - DESKTOP_FOOTER_H;
    let sidebarH = height - DESKTOP_FOOTER_H;

    return (
      <div style={{ ...wrapperStyle, height }}>
        <Toolbar width={DESKTOP_TOOLBAR_W} height={toolbarH} state={extractedState} {...props} />
        <Content width={contentW} height={contentH} state={extractedState} {...props} onWheel={event => event.preventDefault()} />
        <Sidebar width={DESKTOP_SIDEBAR_W} height={sidebarH} state={extractedState} {...props} />
        <FooterBar width={width} height={DESKTOP_FOOTER_H} state={extractedState} {...props} />
      </div>
    );
  }
}

ReactPlanner.propTypes = {
  translator: PropTypes.instanceOf(Translator),
  catalog: PropTypes.instanceOf(Catalog),
  allowProjectFileSupport: PropTypes.bool,
  plugins: PropTypes.arrayOf(PropTypes.func),
  autosaveKey: PropTypes.string,
  autosaveDelay: PropTypes.number,
  width: PropTypes.number.isRequired,
  height: PropTypes.number.isRequired,
  stateExtractor: PropTypes.func.isRequired,
  toolbarButtons: PropTypes.array,
  sidebarComponents: PropTypes.array,
  footerbarComponents: PropTypes.array,
  customContents: PropTypes.object,
  softwareSignature: PropTypes.string
};

ReactPlanner.contextTypes = {
  store: PropTypes.object.isRequired,
};

ReactPlanner.childContextTypes = {
  ...objectsMap(actions, () => PropTypes.object),
  translator: PropTypes.object,
  catalog: PropTypes.object,
};

ReactPlanner.defaultProps = {
  translator: new Translator(),
  catalog: new Catalog(),
  plugins: [],
  allowProjectFileSupport: true,
  softwareSignature: `Idees3d Planner ${VERSION}`,
  toolbarButtons: [],
  sidebarComponents: [],
  footerbarComponents: [],
  customContents: {},
};

//redux connect
function mapStateToProps(reduxState) {
  return {
    state: reduxState
  }
}

function mapDispatchToProps(dispatch) {
  return objectsMap(actions, actionNamespace => bindActionCreators(actions[actionNamespace], dispatch));
}

export default connect(mapStateToProps, mapDispatchToProps)(ReactPlanner);
